import{_ as a,o as t,c as n,a6 as s}from"./chunks/framework.4tsfTCyC.js";const h=JSON.parse('{"title":"Built-in Agent Reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md"}'),i={name:"guide/agents.md"};function o(r,e,l,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="built-in-agent-reference" tabindex="-1">Built-in Agent Reference <a class="header-anchor" href="#built-in-agent-reference" aria-label="Permalink to &quot;Built-in Agent Reference&quot;">​</a></h1><p>TeXRA provides a variety of built-in AI agents designed to assist with different aspects of academic research. Each agent is optimized for specific tasks. You can select these agents from the dropdown menu in the TeXRA UI.</p><p>For details on the underlying structure and execution flow common to all agents, see the <a href="./agent-architecture.html">Agent Architecture &amp; Execution Flow</a> guide.</p><h2 id="correction-polishing-agents" tabindex="-1">Correction &amp; Polishing Agents <a class="header-anchor" href="#correction-polishing-agents" aria-label="Permalink to &quot;Correction &amp; Polishing Agents&quot;">​</a></h2><h3 id="correct" tabindex="-1"><code>correct</code> <a class="header-anchor" href="#correct" aria-label="Permalink to &quot;`correct`&quot;">​</a></h3><p>The <code>correct</code> agent focuses on fixing errors without changing the style or content of your document.</p><p><strong>Purpose:</strong> Fix typos, grammatical errors, and LaTeX syntax issues.</p><p><strong>Best for:</strong></p><ul><li>Final proofreading before submission</li><li>Fixing errors in collaborative documents</li><li>Ensuring consistent formatting and notation</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Fix grammatical errors, typos, and LaTeX syntax issues throughout the document.</span></span>\n<span class="line"><span>Ensure consistent notation for mathematical symbols and equations.</span></span>\n<span class="line"><span>Don&#39;t change the technical content or writing style.</span></span></code></pre></div><h3 id="polish" tabindex="-1"><code>polish</code> <a class="header-anchor" href="#polish" aria-label="Permalink to &quot;`polish`&quot;">​</a></h3><p>The <code>polish</code> agent enhances the writing style and clarity of your document while preserving technical content.</p><p><strong>Purpose:</strong> Improve readability, flow, and overall writing quality.</p><p><strong>Best for:</strong></p><ul><li>Enhancing draft manuscripts</li><li>Making technical content more accessible</li><li>Improving the flow between sections</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Improve the clarity and readability of this document. Make the language more concise</span></span>\n<span class="line"><span>and enhance the flow between paragraphs. Maintain all technical content and equations.</span></span>\n<span class="line"><span>Focus especially on the introduction and discussion sections.</span></span></code></pre></div><h2 id="content-generation-transformation-agents" tabindex="-1">Content Generation &amp; Transformation Agents <a class="header-anchor" href="#content-generation-transformation-agents" aria-label="Permalink to &quot;Content Generation &amp; Transformation Agents&quot;">​</a></h2><h3 id="paper2slide" tabindex="-1"><code>paper2slide</code> <a class="header-anchor" href="#paper2slide" aria-label="Permalink to &quot;`paper2slide`&quot;">​</a></h3><p>The <code>paper2slide</code> agent converts research papers into LaTeX beamer presentations.</p><p><strong>Purpose:</strong> Create presentation slides from academic content.</p><p><strong>Best for:</strong></p><ul><li>Preparing conference presentations</li><li>Converting papers for teaching purposes</li><li>Creating seminar materials</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Convert this paper into a beamer presentation with approximately 15-20 slides.</span></span>\n<span class="line"><span>Include a title slide, outline, introduction, methodology, results, and conclusion.</span></span>\n<span class="line"><span>Use bullet points for clarity and add slide titles. Include the key figures and tables.</span></span></code></pre></div><h3 id="paper2poster" tabindex="-1"><code>paper2poster</code> <a class="header-anchor" href="#paper2poster" aria-label="Permalink to &quot;`paper2poster`&quot;">​</a></h3><p>The <code>paper2poster</code> agent transforms papers into academic conference posters.</p><p><strong>Purpose:</strong> Create well-structured academic posters.</p><p><strong>Best for:</strong></p><ul><li>Conference poster preparation</li><li>Visual research summaries</li><li>Academic showcases</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Convert this paper into an academic poster using the baposter template.</span></span>\n<span class="line"><span>Include sections for Introduction, Methodology, Results, and Conclusions.</span></span>\n<span class="line"><span>Highlight key figures and tables. Make it visually appealing with appropriate columns.</span></span></code></pre></div><h2 id="figure-media-agents" tabindex="-1">Figure &amp; Media Agents <a class="header-anchor" href="#figure-media-agents" aria-label="Permalink to &quot;Figure &amp; Media Agents&quot;">​</a></h2><h3 id="draw" tabindex="-1"><code>draw</code> <a class="header-anchor" href="#draw" aria-label="Permalink to &quot;`draw`&quot;">​</a></h3><p>The <code>draw</code> agent creates or enhances TikZ figures based on textual descriptions or existing figures.</p><p><strong>Purpose:</strong> Generate visual representations of concepts, systems, or data.</p><p><strong>Best for:</strong></p><ul><li>Creating diagrams, flowcharts, or schematics from descriptions</li><li>Improving existing TikZ figures</li><li>Converting descriptions into LaTeX visualizations</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a TikZ figure illustrating a neural network with an input layer (3 nodes),</span></span>\n<span class="line"><span>two hidden layers (5 nodes each), and an output layer (2 nodes).</span></span>\n<span class="line"><span>Use appropriate colors and add labels for each layer.</span></span></code></pre></div><h3 id="ocr" tabindex="-1"><code>ocr</code> <a class="header-anchor" href="#ocr" aria-label="Permalink to &quot;`ocr`&quot;">​</a></h3><p>The <code>ocr</code> agent performs Optical Character Recognition (OCR) on image or PDF files.</p><p><strong>Purpose:</strong> Extract text content from images or non-searchable PDFs.</p><p><strong>Best for:</strong></p><ul><li>Extracting text from scanned documents or figures</li><li>Making image-based text searchable and editable</li><li>Processing figures containing text for analysis</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Perform OCR on the provided image file [figure.png] and extract all text content. Format the output as plain text.</span></span></code></pre></div><h3 id="transcribe-audio" tabindex="-1"><code>transcribe_audio</code> <a class="header-anchor" href="#transcribe-audio" aria-label="Permalink to &quot;`transcribe_audio`&quot;">​</a></h3><p>The <code>transcribe_audio</code> agent converts audio files into text transcripts.</p><p><strong>Purpose:</strong> Create text versions of audio recordings.</p><p><strong>Best for:</strong></p><ul><li>Transcribing interviews or lectures</li><li>Converting meeting recordings to text</li><li>Creating subtitles or notes from audio</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transcribe the provided audio file [interview.mp3]. Provide the output as a plain text file with speaker labels if possible.</span></span></code></pre></div><h2 id="presentation-simplification-agents" tabindex="-1">Presentation &amp; Simplification Agents <a class="header-anchor" href="#presentation-simplification-agents" aria-label="Permalink to &quot;Presentation &amp; Simplification Agents&quot;">​</a></h2><h3 id="presenter" tabindex="-1"><code>presenter</code> <a class="header-anchor" href="#presenter" aria-label="Permalink to &quot;`presenter`&quot;">​</a></h3><p>An interactive scientific presentation builder with visual quality assurance. It creates LaTeX Beamer presentations, posters, and visual materials by surveying your codebase, planning slides, and iteratively compiling and inspecting the output PDF.</p><p><strong>Purpose:</strong> Build publication-ready presentations from research projects.</p><p><strong>Best for:</strong></p><ul><li>Conference talks, poster sessions, and seminar presentations</li><li>Code documentation slides and tutorial materials</li><li>Generating TikZ diagrams and including computed figures</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a 15-slide Beamer presentation from this project. Cover motivation, the core</span></span>\n<span class="line"><span>algorithm, key results, and future work. Use the metropolis theme and include TikZ</span></span>\n<span class="line"><span>diagrams for the architecture. Compile and verify every slide looks correct.</span></span></code></pre></div><h3 id="simplifier" tabindex="-1"><code>simplifier</code> <a class="header-anchor" href="#simplifier" aria-label="Permalink to &quot;`simplifier`&quot;">​</a></h3><p>A code and writing simplification specialist that makes scientific projects clearer and more maintainable while preserving exact correctness.</p><p><strong>Purpose:</strong> Remove duplication, unnecessary abstraction, and prose bloat from code and documents.</p><p><strong>Best for:</strong></p><ul><li>Refactoring research code for clarity</li><li>Tightening manuscript prose and cleaning up LLM-generated artifacts</li><li>Replacing hand-rolled implementations with standard library equivalents</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Simplify the numerical solver in solver.py. Look for duplicated loops that could be</span></span>\n<span class="line"><span>vectorized with NumPy, inline any single-use helper functions, and remove dead code.</span></span>\n<span class="line"><span>Run the existing tests after each change to verify correctness.</span></span></code></pre></div><h2 id="specialized-agents" tabindex="-1">Specialized Agents <a class="header-anchor" href="#specialized-agents" aria-label="Permalink to &quot;Specialized Agents&quot;">​</a></h2><h3 id="merge" tabindex="-1"><code>merge</code> <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;`merge`&quot;">​</a></h3><p>The <code>merge</code> agent intelligently combines changes from an edited document back into a base document.</p><p><strong>Purpose:</strong> Integrate edits from different versions or sources while resolving conflicts.</p><p><strong>Best for:</strong></p><ul><li>Applying AI-suggested edits from a <code>_r0_</code> or <code>_r1_</code> file</li><li>Incorporating reviewer suggestions from a separate file</li><li>Combining different drafts or collaborator edits</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Merge changes from the edited file into the original document (base file). Prioritize substantive</span></span>\n<span class="line"><span>improvements in clarity while maintaining the original&#39;s technical precision.</span></span>\n<span class="line"><span>Preserve mathematical notation and citations from the original.</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Now that you understand the default built-in agents, you might want to learn more:</p><ul><li><a href="./agent-architecture.html">Agent Architecture &amp; Execution Flow</a> - Understand how agents work internally.</li><li><a href="./custom-agents.html">Custom Agents</a> - Learn how to create your own specialized agents.</li><li><a href="/guide/models.html">Models</a> - Learn about the different AI models and their capabilities.</li></ul>',81)])])}const u=a(i,[["render",o]]);export{h as __pageData,u as default};
